    chapter: 'فصل في إخراج الضرب',
    chapterHebrew: 'המשך תפילת הפתיחה + פרק: הוצאת הגורל',
    arabicText: `{وعنده مفاتح الغيب لا يعلمها إلا هو ويعلم ما في البر والبحر وما تسقط من ورقة إلا يعلمها ولا حبة في ظلمات الأرض ولا رطب ولا يابس إلا في كتاب مبين} (١)، وتقول: اللهم إن علم الغيب كله عندك، وأنت أعلم به مني، فأسألك كشف ما حجبته عني، فقد قلت، وأنت أصدق القائلين: {أو أثارة من علم إن كنتم صادقين} (٢).
وينبغي أن تقرأ عند ضربك الخط الأول: الفاتحة؛ وعند الثاني: آية الكرسي؛ وعند الثالث: اللهم أرني في هذا الخط ما هو في سرك المكنون، وفي غيبك المكتوم، برحمتك يا أرحم الراحمين؛ وعند الرابع: {وعنده مفاتح الغيب لا يعلمها إلا هو ويعلم ما في البر والبحر وما تسقط من ورقة إلا يعلمها ولا حبة في ظلمات الأرض ولا رطب ولا يابس إلا في كتاب مبين} (١).
فصل في إخراج الضرب:
ثم تضرب خطا، أربعة أسطر من غير عد، ويكون كل سطر بالظن، أنه يزيد على إثني عشر نقطة؛ ويكون السطر الثاني أزيد من الأول؛ والثالث أزيد من الثاني؛ والرابع أزيد من
(١) سورة الأنعام: 59
(٢) سورة الأحقاف: 4`,
    hebrewTranslation: `"ואצלו מפתחות הנסתר — לא יודע אותן אלא הוא; יודע מה שביבשה ובים; ולא תיפול עלה אלא יודעה, ולא גרגיר בחשכת האדמה, ולא לח ולא יבש — אלא בכתב מבין" (סורה אל-אנעאם: 59). ותאמר: אלוהים, כל מדע הנסתר אצלך, ואתה יודעו ממני — אבקשך לגלות לי מה שהסתרת ממני, שכן אמרת, ואתה האמיתי מכל: "או רמז ממדע, אם אמת בפיכם" (סורה אל-אחקאף: 4).
ראוי שתקרא בעת ציור הקו הראשון: הפאתחה. בשני: אית אל-כורסי. בשלישי: "אלוהים, הראה לי בקו זה מה שבסודך הצפון ובנסתרך הכתוב, ברחמיך יא רחם הרחמנים." ברביעי: "ואצלו מפתחות הנסתר..." (הפסוק המלא).

פרק: הוצאת הגורל:
אחר כך צייר קו — ארבעה שורות ללא ספירה; כל שורה תהיה לפי הערכה יותר משתים-עשרה נקודות. השורה השנייה תהיה יותר מהראשונה; השלישית יותר מהשנייה; הרביעית יותר מ...`,
